typedef struct {
    double x, y, r;
} Circle;

static double sqr(double x) { return x * x; }

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Circle *c = (Circle *)malloc((size_t)n * sizeof(Circle));
    if (!c) return 0;

    for (int i = 0; i < n; ++i) {
        scanf("%lf %lf %lf", &c[i].x, &c[i].y, &c[i].r);
    }

    /*
      The path must always stay inside at least one circle.
      Since the circles form a chain, movement from circle i to i+1
      is possible only through their intersection/overlap.

      The shortest such path from center of first to center of last
      equals:
        dist(center1, centern)
        minus the parts that can be "saved" by starting inside circle 1
        and ending inside circle n,
      which is:
        max(0, d - r1 - rn) for two circles,
      generalized over a chain as sum of gaps between consecutive circles,
      plus entering/exiting from the endpoint centers.

      Equivalently:
        answer = sum over consecutive centers distances
                 - sum over consecutive radius cover
      collapsed to:
        r1 + rn + sum(max(0, d(i,i+1) - ri - r(i+1)))
      where the first and last centers must be reached from inside
      their own circles, contributing r1 and rn.
    */

    double ans = c[0].r + c[n - 1].r;

    for (int i = 0; i + 1 < n; ++i) {
        double dx = c[i + 1].x - c[i].x;
        double dy = c[i + 1].y - c[i].y;
        double d = sqrt(dx * dx + dy * dy);
        double gap = d - c[i].r - c[i + 1].r;
        if (gap > 0) ans += gap;
    }

    printf("%.10f\n", ans);

    free(c);
    return 0;
}

