double dist(double x1, double y1, double x2, double y2) {
    return hypot(x2 - x1, y2 - y1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Circle> circles(n);
    for (int i = 0; i < n; ++i) {
        cin >> circles[i].x >> circles[i].y >> circles[i].r;
    }

    vector<vector<pair<int, double>>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double d = dist(circles[i].x, circles[i].y, circles[j].x, circles[j].y);
            double rsum = circles[i].r + circles[j].r;
            if (d <= rsum + 1e-9) {
                double edgeWeight = max(0.0, d - circles[i].r - circles[j].r);
                adj[i].emplace_back(j, edgeWeight);
                adj[j].emplace_back(i, edgeWeight);
            }
        }
    }

    // Dijkstra from circle 0 to circle n-1
    vector<double> distTo(n, numeric_limits<double>::infinity());
    distTo[0] = 0.0;
    priority_queue<pair<double, int>, vector<pair<double, int>>, greater<>> pq;
    pq.emplace(0.0, 0);

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > distTo[u] + 1e-9) continue;
        if (u == n - 1) break;
        for (auto [v, w] : adj[u]) {
            double nd = d + w;
            if (nd < distTo[v] - 1e-9) {
                distTo[v] = nd;
                pq.emplace(nd, v);
            }
        }
    }

    cout << fixed << setprecision(10) << distTo[n-1] << "\n";
    return 0;
}

