struct DSU {
    vector<int> p, r;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        r.assign(n, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<double> x(n), y(n), r(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> y[i] >> r[i];
    }

    // Build connected components of the union of circles.
    DSU dsu(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double dx = x[i] - x[j];
            double dy = y[i] - y[j];
            double dist2 = dx * dx + dy * dy;
            double sr = r[i] + r[j];
            if (dist2 <= sr * sr + 1e-12) {
                dsu.unite(i, j);
            }
        }
    }

    // Since the circles form a chain, first and last are connected through overlaps.
    // Then the straight segment between their centers lies entirely in the connected union,
    // and its length is the minimum possible.
    double dx = x[0] - x[n - 1];
    double dy = y[0] - y[n - 1];
    double ans = sqrt(dx * dx + dy * dy);

    cout.setf(ios::fixed);
    cout << setprecision(10) << ans << '\n';
    return 0;
}

