public class Main {
    static final double EPS = 1e-9;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read circles: x, y, r
        List<double[]> circles = new ArrayList<>();
        while (sc.hasNextDouble()) {
            double x = sc.nextDouble(), y = sc.nextDouble(), r = sc.nextDouble();
            circles.add(new double[]{x, y, r});
        }
        int n = circles.size();
        if (n == 1) { System.out.printf("%.6f%n", 0.0); return; }

        List<double[]> pts = new ArrayList<>();
        for (double[] c : circles) pts.add(new double[]{c[0], c[1]});

        for (int i = 0; i < n; i++) for (int j = i+1; j < n; j++) {
            double[] A = circles.get(i), B = circles.get(j);
            double dx = B[0]-A[0], dy = B[1]-A[1], d = Math.sqrt(dx*dx+dy*dy);
            if (d < EPS || d > A[2]+B[2]+EPS || d < Math.abs(A[2]-B[2])-EPS) continue;
            double a = (A[2]*A[2]-B[2]*B[2]+d*d)/(2*d);
            double h = Math.sqrt(Math.max(0,A[2]*A[2]-a*a));
            double mx = A[0]+a*dx/d, my = A[1]+a*dy/d;
            pts.add(new double[]{mx+h*dy/d, my-h*dx/d});
            pts.add(new double[]{mx-h*dy/d, my+h*dx/d});
        }

        int m = pts.size();
        double[] dist = new double[m]; Arrays.fill(dist, Double.MAX_VALUE); dist[0] = 0;
        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(x->x[0]));
        pq.offer(new double[]{0, 0});
        while (!pq.isEmpty()) {
            double[] cur = pq.poll(); double cd = cur[0]; int u = (int)cur[1];
            if (cd > dist[u]+EPS) continue;
            double[] P = pts.get(u);
            for (int v = 0; v < m; v++) {
                double[] Q = pts.get(v);
                for (double[] c : circles) {
                    double d1 = Math.sqrt((P[0]-c[0])*(P[0]-c[0])+(P[1]-c[1])*(P[1]-c[1]));
                    double d2 = Math.sqrt((Q[0]-c[0])*(Q[0]-c[0])+(Q[1]-c[1])*(Q[1]-c[1]));
                    if (d1 <= c[2]+EPS && d2 <= c[2]+EPS) {
                        double w = Math.sqrt((P[0]-Q[0])*(P[0]-Q[0])+(P[1]-Q[1])*(P[1]-Q[1]));
                        if (dist[u]+w < dist[v]-EPS) { dist[v]=dist[u]+w; pq.offer(new double[]{dist[v],v}); }
                        break;
                    }
                }
            }
        }
        System.out.printf("%.6f%n", dist[1]);
    }
}

import java.io.*;
import java.util.*;

/*
We model each circle center as a node.
A valid path must always stay inside at least one circle, so movement is only possible
through regions covered by circles. For two circles, if they overlap or touch, then one
can move from one center to the other while staying inside the union of those two circles.
Thus we build a graph where circles are connected if the distance between centers is
<= sum of radii.

The shortest valid path from center of first circle to center of last circle is then
the shortest path in this graph, where the cost of moving directly between two connected
centers is the Euclidean distance between them.

We use Dijkstra.

Input format assumed:
n
x1 y1 r1
x2 y2 r2
...
xn yn rn

Output:
shortest distance

If unreachable, output -1.
*/

public class Main {
    static class Circle {
        double x, y, r;
        Circle(double x, double y, double r) {
            this.x = x;
            this.y = y;
            this.r = r;
        }
    }

    static class Edge {
        int to;
        double w;
        Edge(int to, double w) {
            this.to = to;
            this.w = w;
        }
    }

    static class State implements Comparable<State> {
        int v;
        double d;
        State(int v, double d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(State o) {
            return Double.compare(this.d, o.d);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        if (!fs.hasNext()) return;
        n = fs.nextInt();

        Circle[] c = new Circle[n];
        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            double r = fs.nextDouble();
            c[i] = new Circle(x, y, r);
        }

        List<Edge>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double dx = c[i].x - c[j].x;
                double dy = c[i].y - c[j].y;
                double dist = Math.hypot(dx, dy);
                if (dist <= c[i].r + c[j].r + 1e-12) {
                    g[i].add(new Edge(j, dist));
                    g[j].add(new Edge(i, dist));
                }
            }
        }

        double[] dist = new double[n];
        Arrays.fill(dist, Double.POSITIVE_INFINITY);
        dist[0] = 0.0;

        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.add(new State(0, 0.0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.d > dist[cur.v] + 1e-12) continue;
            if (cur.v == n - 1) break;

            for (Edge e : g[cur.v]) {
                double nd = cur.d + e.w;
                if (nd + 1e-12 < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new State(e.to, nd));
                }
            }
        }

        if (Double.isInfinite(dist[n - 1])) {
            System.out.println(-1);
        } else {
            System.out.printf(Locale.US, "%.10f%n", dist[n - 1]);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean hasNext() throws IOException {
            int c;
            while ((c = read()) != -1) {
                if (!Character.isWhitespace(c)) {
                    ptr--;
                    return true;
                }
            }
            return false;
        }

        String next() throws IOException {
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char)c);
                c = read();
            } while (c != -1 && !Character.isWhitespace(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
